import React, { useState } from 'react';
import { signInWithEmailAndPassword, signInWithPopup, GoogleAuthProvider } from 'firebase/auth';
import { auth } from '../firebase/firebaseConfig';
import { useNavigate } from 'react-router-dom';

const Login = () => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [errorMessage, setErrorMessage] = useState('');
    const navigate = useNavigate();

    // Handle Email/Password Login
    const handleLogin = async () => {
        try {
            await signInWithEmailAndPassword(auth, email, password);
            navigate('/employees');
        } catch (error: any) {
            // Handling different Firebase errors
            if (error.code === "auth/invalid-credential") {
                setErrorMessage("Invalid email or password. Please try again.");
            } else if (error.code === "auth/user-not-found") {
                setErrorMessage("No account found with this email. Please sign up.");
            } else if (error.code === "auth/wrong-password") {
                setErrorMessage("Incorrect password. Try again or reset your password.");
            } else if (error.code === "auth/too-many-requests") {
                setErrorMessage("Too many failed attempts. Try again later or reset your password.");
            } else {
                setErrorMessage("Login failed. Please try again.");
            }
            console.error("Firebase Login Error:", error.code, error.message);
        }
    };

    // Handle Google Login
    const handleGoogleLogin = async () => {
        const provider = new GoogleAuthProvider();
        try {
            await signInWithPopup(auth, provider);
            navigate('/employees');
        } catch (error) {
            setErrorMessage("Google login failed. Please try again.");
            console.error("Google Login Error:", error);
        }
    };

    return (
        <div style={{ textAlign: "center", maxWidth: "400px", margin: "50px auto", padding: "20px", border: "1px solid #ddd", borderRadius: "10px" }}>
            <h2>Login</h2>

            {errorMessage && <p style={{ color: "red" }}>{errorMessage}</p>}

            <div>
                <input
                    type="email"
                    placeholder="Email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    style={{ width: "100%", padding: "8px", margin: "5px 0" }}
                />
            </div>
            <div>
                <input
                    type="password"
                    placeholder="Password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    style={{ width: "100%", padding: "8px", margin: "5px 0" }}
                />
            </div>

            <button onClick={handleLogin} style={{ width: "100%", padding: "10px", marginTop: "10px", backgroundColor: "#007bff", color: "white", border: "none", cursor: "pointer" }}>
                Login
            </button>

            <button onClick={handleGoogleLogin} style={{ width: "100%", padding: "10px", marginTop: "10px", backgroundColor: "#db4437", color: "white", border: "none", cursor: "pointer" }}>
                Login with Google
            </button>

            <div style={{ marginTop: "10px" }}>
                <button onClick={() => navigate('/forgot-password')} style={{ background: "none", border: "none", color: "#007bff", cursor: "pointer" }}>
                    Forgot Password?
                </button>
            </div>

            <div>
                <button onClick={() => navigate('/signup')} style={{ background: "none", border: "none", color: "#007bff", cursor: "pointer" }}>
                    Sign Up
                </button>
            </div>
        </div>
    );
};

export default Login;
